{"script":"() => {
  const items = document.querySelectorAll('li');
  const results = [];
  items.forEach(li => {
    const titleEl = li.querySelector('h3 a');
    const text = li.innerText;
    if (titleEl && text) {
      results.push({
        title: titleEl.innerText.trim(),
        text: text.substring(0, 300)
      });
    }
  });
  return results;
}"}

